import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../../context/AuthContext';
import styles from './Header.module.css';

const Header = () => {
    const navigate = useNavigate();
    const { user, logout, isAuthenticated } = useAuth();
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

    const isAdmin = user?.isAdmin === true;

    const handleLogout = () => {
        logout();
        navigate('/');
    };
    
    const theme = localStorage.getItem('theme') || 'light';
    const logoSrc = theme === 'dark' ? '/assets/images/logo.png' : '/assets/images/logo_t.png';

    return (
        <header className={styles.header}>
            <div className={styles.container}>
                <Link to="/" className={styles.logo}>
                    <img src={logoSrc} alt="Volley Hub" className={styles.logoImage} />
                    <span className={styles.logoText}>Volley Hub</span>
                </Link>

                <button
                    className={styles.mobileMenuButton}
                    onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                >
                    ☰
                </button>

                <nav className={`${styles.nav} ${mobileMenuOpen ? styles.navOpen : ''}`}>
                    <Link to="/" className={styles.navLink} onClick={() => setMobileMenuOpen(false)}>Главная</Link>
                    <Link to="/about" className={styles.navLink} onClick={() => setMobileMenuOpen(false)}>О нас</Link>

                    {isAuthenticated && (
                        <>
                            <Link to="/notifications" className={styles.navLink} onClick={() => setMobileMenuOpen(false)}>Уведомления</Link>
                            <Link to="/profile" className={styles.navLink} onClick={() => setMobileMenuOpen(false)}>Профиль</Link>
                            {isAdmin && (
                                <>
                                    <Link to="/admin/users" className={styles.navLink} onClick={() => setMobileMenuOpen(false)}>Пользователи</Link>
                                    <Link to="/admin/statistics" className={styles.navLink} onClick={() => setMobileMenuOpen(false)}>Статистика</Link>
                                </>
                            )}
                        </>
                    )}

                    {isAuthenticated ? (
                        <button onClick={handleLogout} className={styles.logoutButton}>Выйти</button>
                    ) : (
                        <div className={styles.authButtons}>
                            <Link to="/login" className={styles.loginButton} onClick={() => setMobileMenuOpen(false)}>Войти</Link>
                            <Link to="/register" className={styles.registerButton} onClick={() => setMobileMenuOpen(false)}>Регистрация</Link>
                        </div>
                    )}
                </nav>
            </div>
        </header>
    );
};

export default Header;
